create table if not exists public.blocks(id uuid primary key default gen_random_uuid(),blocker_id uuid not null references auth.users(id) on delete cascade,blocked_user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),unique(blocker_id,blocked_user_id));create index if not exists blocks_blocker_idx on public.blocks(blocker_id);create index if not exists blocks_blocked_idx on public.blocks(blocked_user_id);alter table public.blocks enable row level security;drop policy if exists blocks_self on public.blocks;create policy blocks_self on public.blocks for all using(auth.uid()=blocker_id) with check(auth.uid()=blocker_id);create index if not exists conversations_user_created_idx on public.conversations(user_id,created_at desc);create index if not exists improvements_user_status_idx on public.improvement_items(user_id,status,last_seen desc);